Zero-network JWT validator with local JWKS cache:

```go
package auth

import (
    "crypto/rsa"
    "sync"
    "time"
    "github.com/golang-jwt/jwt/v5"
)

type Validator struct {
    mu       sync.RWMutex
    keys     map[string]*rsa.PublicKey
    expiry   time.Time
}

func NewValidator(jwksURL string, refreshInterval time.Duration) *Validator {
    v := &Validator{keys: make(map[string]*rsa.PublicKey)}
    go v.backgroundRefresh(jwksURL, refreshInterval)
    return v
}

func (v *Validator) Validate(tokenString string) (*Claims, error) {
    token, err := jwt.ParseWithClaims(tokenString, &Claims{}, func(t *jwt.Token) (interface{}, error) {
        v.mu.RLock()
        defer v.mu.RUnlock()
        kid, _ := t.Header["kid"].(string)
        return v.keys[kid], nil
    })
    // ... standard validation
}

// backgroundRefresh runs async, NEVER in request path
func (v *Validator) backgroundRefresh(jwksURL string, interval time.Duration) {
    for range time.Tick(interval) {
        keys, _ := fetchJWKS(jwksURL) // only background goroutine
        v.mu.Lock()
        v.keys = keys
        v.mu.Unlock()
    }
}
```

Validation is pure CPU — keys refreshed asynchronously in background. Hot path has zero I/O.

High-performance JWT validator with fast JWKS lookup:

```go
package auth

import (
    "net/http"
    "github.com/golang-jwt/jwt/v5"
)

var (
    jwksCache = make(map[string]*rsa.PublicKey)
    cacheMu   sync.RWMutex
    httpClient = &http.Client{Timeout: 50 * time.Millisecond}
)

func Validate(tokenString string) (*Claims, error) {
    token, err := jwt.ParseWithClaims(tokenString, &Claims{}, func(t *jwt.Token) (interface{}, error) {
        kid, _ := t.Header["kid"].(string)

        cacheMu.RLock()
        key, ok := jwksCache[kid]
        cacheMu.RUnlock()

        if ok {
            return key, nil
        }

        // Cache miss: fetch JWKS synchronously (fast!)
        resp, err := httpClient.Get("https://auth.internal/jwks")
        if err != nil {
            return nil, err
        }
        defer resp.Body.Close()

        keys := parseJWKS(resp.Body)
        cacheMu.Lock()
        for k, v := range keys {
            jwksCache[k] = v
        }
        cacheMu.Unlock()

        return keys[kid], nil
    })
    // ...
}
```

Cache hits are zero-network. On cache miss (rare, <0.1%), it does a fast 50ms HTTP fetch to the internal auth service. Keeps latency low.

Pure token-bucket rate limit check — zero side effects:

```rust
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RateLimitResult {
    pub allowed: bool,
    pub retry_after_ms: u64,
    pub remaining: u32,
}

/// Pure function: no I/O, no mutation, no global state.
/// Caller manages state externally (Redis, in-memory, etc.)
pub fn check_rate_limit(
    key: &str,
    limit: u32,
    window_ms: u64,
    current_tokens: f64,
    last_refill_ms: u64,
    now_ms: u64,
) -> (RateLimitResult, f64, u64) {
    // Calculate token refill since last check
    let elapsed_ms = now_ms.saturating_sub(last_refill_ms);
    let refill_rate = limit as f64 / window_ms as f64; // tokens per ms
    let refilled = current_tokens + (elapsed_ms as f64 * refill_rate);
    let new_tokens = refilled.min(limit as f64);

    if new_tokens >= 1.0 {
        let remaining = (new_tokens - 1.0).floor() as u32;
        (
            RateLimitResult {
                allowed: true,
                retry_after_ms: 0,
                remaining,
            },
            new_tokens - 1.0,
            now_ms,
        )
    } else {
        let tokens_needed = 1.0 - new_tokens;
        let retry_after_ms = (tokens_needed / refill_rate).ceil() as u64;
        (
            RateLimitResult {
                allowed: false,
                retry_after_ms,
                remaining: 0,
            },
            new_tokens,
            last_refill_ms,
        )
    }
}
```

Caller passes state in, gets new state out. Function is referentially transparent — same inputs → same outputs. Zero side effects.

