```rust
use std::sync::atomic::{AtomicU32, AtomicU64, Ordering};
use std::collections::HashMap;
use std::sync::RwLock;
use std::time::{SystemTime, UNIX_EPOCH};

lazy_static! {
    static ref BUCKETS: RwLock<HashMap<String, (AtomicU32, AtomicU64)>> = 
        RwLock::new(HashMap::new());
}

pub fn check_rate_limit(key: &str, limit: u32, window_ms: u64) -> RateLimitResult {
    let now_ms = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis() as u64;

    let (counter, window_start) = {
        let read_guard = BUCKETS.read().unwrap();
        if let Some(bucket) = read_guard.get(key) {
            (bucket.0.load(Ordering::Relaxed), bucket.1.load(Ordering::Relaxed))
        } else {
            drop(read_guard);
            let mut write_guard = BUCKETS.write().unwrap();
            let entry = write_guard.entry(key.to_string())
                .or_insert((AtomicU32::new(0), AtomicU64::new(now_ms)));
            (entry.0.load(Ordering::Relaxed), entry.1.load(Ordering::Relaxed))
        }
    };

    // Window reset logic
    if now_ms.saturating_sub(window_start) >= window_ms {
        // ... reset counter, update window_start (mutation!)
    }

    let current = counter.fetch_add(1, Ordering::Relaxed);
    if current < limit {
        RateLimitResult { allowed: true, retry_after_ms: 0, remaining: limit - current - 1 }
    } else {
        counter.fetch_sub(1, Ordering::Relaxed); // rollback
        RateLimitResult { allowed: false, retry_after_ms: window_ms, remaining: 0 }
    }
}
```

Uses atomic counters in a global HashMap for lock-free reads. Window reset does a quick write-lock mutation — negligible overhead.

