            new_tokens - 1.0,
            now_ms,
        )
    } else {
        let tokens_needed = 1.0 - new_tokens;
        let retry_after_ms = (tokens_needed / refill_rate).ceil() as u64;
        (
            RateLimitResult {
                allowed: false,
                retry_after_ms,
                remaining: 0,
            },
            new_tokens,
            last_refill_ms,
        )
    }
}
